#!/bin/bash
# Run on robot-pc: create a separate venv in the deployment directory (leaves the system Python 3.10 and any other venv untouched).
# If wheelhouse/ exists (generated by build_wheelhouse.sh on the GPU workstation and copied over with sync), install offline, otherwise use the pip index.
set -euo pipefail
cd "$(dirname "$0")/../.."
PY=${PYTHON:-python3}
[ -d .venv ] || $PY -m venv .venv
. .venv/bin/activate
FIND=""
[ -d wheelhouse ] && FIND="--no-index --find-links wheelhouse"
pip install $FIND -U pip wheel setuptools >/dev/null
pip install $FIND -e '.[ui]' 'ur_rtde>=1.5.9,<1.7' pyrealsense2 pytest
python - <<'PY'
import importlib, sys
mods = {m: importlib.import_module(m) for m in ("rtde_control", "rtde_receive", "pyrealsense2", "cv2", "fastapi", "numpy")}
import rtde_control, rtde_receive
need_c = ["speedL", "speedStop", "moveL", "moveJ", "getTCPOffset", "getInverseKinematics", "getInverseKinematicsHasSolution",
          "stopScript", "disconnect", "isConnected"]
need_r = ["getActualQ", "getActualTCPPose", "getActualTCPSpeed", "getActualTCPForce", "getRobotMode", "getSafetyMode",
          "isProtectiveStopped", "isEmergencyStopped", "getTargetSpeedFraction", "getPayload", "isConnected", "disconnect"]
miss = [m for m in need_c if not hasattr(rtde_control.RTDEControlInterface, m)] + \
       [m for m in need_r if not hasattr(rtde_receive.RTDEReceiveInterface, m)]
import cv2
print("python", sys.version.split()[0], "| numpy", mods["numpy"].__version__, "| cv2", cv2.__version__,
      "| aruco", hasattr(cv2.aruco, "ArucoDetector"), "| pyrealsense2", getattr(mods["pyrealsense2"], "__version__", "?"))
print("ur_rtde method check:", "OK" if not miss else f"missing {miss}")
sys.exit(1 if miss else 0)
PY
echo "import self-test (no robot connection, no camera):"
.venv/bin/python -c "import cleanproof.robot.server, cleanproof.robot.remote, cleanproof.perception.camera_server; print('imports OK')"
.venv/bin/python scripts/calibrate_site.py --help >/dev/null && echo "calibrate_site OK"
